from scipy import ndimage
def shapes(g, c):
    m = g==c
    lab,n = ndimage.label(m, structure=np.ones((3,3)))
    out=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        sub=(lab[ys.min():ys.max()+1, xs.min():xs.max()+1]==i).astype(int)
        out.append((len(ys), sub.shape, sub))
    return out
