def variants(t):
    outs=[]
    a=t
    for _ in range(4):
        for f in [a, a[:,::-1]]:
            outs.append(f)
        a=np.rot90(a)
    # dedupe
    uq=[]
    for v in outs:
        if not any(v.shape==u.shape and (v==u).all() for u in uq): uq.append(v)
    return uq
